 const findNext=(needle:string)=>{if(!editor.current)return false;const walker=document.createTreeWalker(editor.current,NodeFilter.SHOW_TEXT);const nodes:Text[]=[];for(let node=walker.nextNode();node;node=walker.nextNode())nodes.push(node as Text);if(!nodes.length)return false;const selection=getSelection();const active=selection?.rangeCount&&editor.current.contains(selection.anchorNode)?selection.getRangeAt(0):null;let startIndex=0,startOffset=0;if(active){const at=nodes.indexOf(active.endContainer as Text);if(at>=0){startIndex=at;startOffset=active.endOffset}}const lowerNeedle=needle.toLocaleLowerCase();const search=(from:number,fromOffset:number,to:number)=>{for(let index=from;index<to;index++){const lower=(nodes[index].textContent??"").toLocaleLowerCase();const at=lower.indexOf(lowerNeedle,index===from?fromOffset:0);if(at>=0)return{index,at}}return null};const match=search(startIndex,startOffset,nodes.length)??search(0,0,startIndex+1);if(!match)return false;const range=document.createRange();range.setStart(nodes[match.index],match.at);range.setEnd(nodes[match.index],match.at+needle.length);selection?.removeAllRanges();selection?.addRange(range);savedRange.current=range;range.startContainer.parentElement?.scrollIntoView({block:"center"});return true};
